import { EditorView } from '@codemirror/view';
import { HighlightStyle, syntaxHighlighting } from '@codemirror/language';
import { tags as t } from '@lezer/highlight';

// Colors reused from tailwind.config.js so the editor matches the rest of the builder UI
// instead of importing a separate CodeMirror theme package.
const COLORS = {
    text: '#303030', // colors.text.primary
    textSecondary: '#616161', // colors.text.secondary
    border: '#8A8A8A', // borderColor.input.DEFAULT
    borderHover: '#616161', // borderColor.input.hover
    focus: '#005BD3', // colors.focus
    surface: '#F7F7F7', // backgroundColor.surface.secondary.DEFAULT
    danger: '#D82C0D', // colors.danger.600
    gray300: '#AEB4B9' // colors.gray.300
};

export const lightEditorTheme = EditorView.theme(
    {
        '&': {
            color: COLORS.text,
            backgroundColor: '#fff',
            height: '100%',
            fontSize: '12px'
        },
        '.cm-content': {
            caretColor: COLORS.focus,
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace'
        },
        '.cm-cursor, .cm-dropCursor': { borderLeftColor: COLORS.focus },
        '&.cm-focused .cm-selectionBackground, .cm-selectionBackground, .cm-content ::selection': {
            backgroundColor: '#cfe4fb'
        },
        '.cm-gutters': {
            backgroundColor: COLORS.surface,
            color: COLORS.textSecondary,
            border: 'none',
            borderRight: `1px solid ${COLORS.gray300}`
        },
        '.cm-activeLine': { backgroundColor: 'rgba(0, 91, 211, 0.05)' },
        '.cm-activeLineGutter': { backgroundColor: 'rgba(0, 91, 211, 0.08)' },
        '.cm-lintRange-warning': {
            backgroundImage: 'none',
            textDecoration: `underline wavy ${COLORS.danger}`,
            textUnderlineOffset: '2px'
        },
        '.cm-tooltip.cm-tooltip-lint': {
            fontSize: '12px',
            border: `1px solid ${COLORS.border}`,
            borderRadius: '8px',
            overflow: 'hidden'
        },
        '&.cm-editor.cm-focused': { outline: 'none' }
    },
    { dark: false }
);

export const lightHighlightStyle = HighlightStyle.define([
    { tag: t.comment, color: '#8A8A8A', fontStyle: 'italic' },
    { tag: [t.keyword, t.controlKeyword, t.operatorKeyword], color: '#005BD3' },
    { tag: [t.string, t.special(t.string)], color: '#2BAE6C' },
    { tag: [t.number, t.bool, t.null], color: '#9f200a' },
    { tag: [t.definition(t.variableName), t.function(t.variableName)], color: '#00A2BB' },
    { tag: t.variableName, color: COLORS.text },
    { tag: [t.propertyName, t.attributeName], color: '#8E1F0B' },
    { tag: [t.tagName], color: '#005BD3' },
    { tag: [t.angleBracket], color: COLORS.textSecondary },
    { tag: [t.className, t.typeName], color: '#155e75' },
    { tag: t.attributeValue, color: '#2BAE6C' },
    { tag: t.punctuation, color: COLORS.textSecondary },
    { tag: t.invalid, color: COLORS.danger }
]);

export const codeEditorTheme = [lightEditorTheme, syntaxHighlighting(lightHighlightStyle)];
