import { Liquid, type TagToken, type TopLevelToken } from 'liquidjs';

interface TagImplOptions {
    parse?(this: unknown, token: TagToken, remainingTokens: TopLevelToken[]): void;
    render(this: unknown): string;
}

// Shopify's Liquid dialect has tags that don't exist in the plain liquidjs engine
// (schema, paginate, style, stylesheet, form, javascript). We only care about catching
// genuine structural mistakes (an unbalanced/unclosed tag), not full Shopify semantics,
// so these are registered as permissive pass-through tags: block tags swallow tokens up
// to their matching end tag (and complain if EOF is reached first, same as liquidjs's
// own built-in `raw`/`capture` tags do), single tags accept any content and no-op.
//
// `render`, `include`, `layout`, `section`(s)-as-render are already handled natively by
// liquidjs, so they're not listed here.

function isEndTag(token: TopLevelToken, name: string): boolean {
    return typeof (token as TagToken).name === 'string' && (token as TagToken).name === name;
}

function permissiveBlockTag(endName: string): TagImplOptions {
    return {
        parse(tagToken: TagToken, remainingTokens: TopLevelToken[]) {
            while (remainingTokens.length) {
                const token = remainingTokens.shift() as TopLevelToken;
                if (isEndTag(token, endName)) return;
            }
            throw new Error(`tag ${tagToken.getText()} not closed`);
        },
        render() {
            return '';
        }
    };
}

function permissiveSingleTag(): TagImplOptions {
    return {
        parse() {
            // accept any arguments without validating them
        },
        render() {
            return '';
        }
    };
}

const PERMISSIVE_BLOCK_TAGS: Record<string, string> = {
    schema: 'endschema',
    style: 'endstyle',
    stylesheet: 'endstylesheet',
    javascript: 'endjavascript',
    form: 'endform',
    paginate: 'endpaginate'
};

const PERMISSIVE_SINGLE_TAGS = ['section', 'sections'];

let cachedEngine: Liquid | null = null;

export function createLiquidEngine(): Liquid {
    if (cachedEngine) return cachedEngine;

    const engine = new Liquid({ strictFilters: false, strictVariables: false });

    for (const [tagName, endTagName] of Object.entries(PERMISSIVE_BLOCK_TAGS)) {
        engine.registerTag(tagName, permissiveBlockTag(endTagName));
    }
    for (const tagName of PERMISSIVE_SINGLE_TAGS) {
        engine.registerTag(tagName, permissiveSingleTag());
    }

    cachedEngine = engine;
    return engine;
}
