// Liquid tags ({{ }} / {% %}) are not valid HTML/CSS/JS on their own, so before handing
// code to a language-specific validator we blank them out in place (same length, so
// diagnostic offsets still map back to the original source).
//
// {{ output }} tags are replaced with an identifier-safe placeholder (they're often used
// as a value, e.g. `color: {{ settings.color }};` or `var x = {{ settings.value }};`).
// {% tag %} statements are replaced with plain whitespace (they're always statement-level,
// never an inline value).

const OUTPUT_TAG_RE = /\{\{-?[\s\S]*?-?\}\}/g;
const STATEMENT_TAG_RE = /\{%-?[\s\S]*?-?%\}/g;

function blank(match: string, placeholderChar: string): string {
    let out = '';
    for (let i = 0; i < match.length; i++) {
        out += match[i] === '\n' ? '\n' : placeholderChar;
    }
    return out;
}

export function maskLiquid(code: string): string {
    return code
        .replace(OUTPUT_TAG_RE, (match) => blank(match, 'x'))
        .replace(STATEMENT_TAG_RE, (match) => blank(match, ' '));
}
