// Lightweight HTML tag-balance checker.
//
// We don't use a full spec-compliant parser (e.g. parse5) here: real browsers silently
// auto-close/auto-recover from most "unclosed tag" and "stray closing tag" situations per
// the WHATWG parsing algorithm, so a spec-accurate parser's error events almost never fire
// for the mistakes people actually make (verified empirically against parse5). This scanner
// instead tracks an explicit open-tag stack and flags exactly those two intuitive mistakes,
// while still tolerating the common HTML5 "optional end tag" patterns (<li>, <p>, <tr>, ...)
// so it doesn't false-positive on ordinary markup.

export interface HtmlIssue {
    from: number;
    to: number;
    message: string;
}

const VOID_ELEMENTS = new Set([
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
]);

const RAW_TEXT_ELEMENTS = new Set(['script', 'style', 'textarea', 'title']);

// When one of these tags opens, it silently closes an already-open tag of the same name
// (or, for table sections, any sibling section) still sitting on top of the stack — this
// mirrors HTML5's "optional end tag" auto-close behavior.
const AUTO_CLOSE_ON_SIBLING: Record<string, string[]> = {
    li: ['li'],
    dt: ['dt', 'dd'],
    dd: ['dt', 'dd'],
    option: ['option'],
    tr: ['tr'],
    td: ['td', 'th'],
    th: ['td', 'th'],
    thead: ['thead', 'tbody', 'tfoot'],
    tbody: ['thead', 'tbody', 'tfoot'],
    tfoot: ['thead', 'tbody', 'tfoot']
};

// These tags are also silently closed when an ANCESTOR closes (e.g. </tr> implicitly
// closing a still-open <td>, or </ul> implicitly closing a still-open <li>) — real browsers
// don't treat that as a mistake, so neither do we.
const OPTIONAL_END_TAGS = new Set([
    'li', 'dt', 'dd', 'option', 'tr', 'td', 'th', 'thead', 'tbody', 'tfoot', 'p'
]);

// Inline/"phrasing" tags don't implicitly close an open <p> the way block-level tags do.
const PHRASING_TAGS = new Set([
    'a', 'b', 'i', 'span', 'strong', 'em', 'small', 'code', 'br', 'img', 'sub', 'sup', 'u',
    'mark', 'abbr', 'cite', 'q', 'kbd', 'samp', 'var', 'time', 'label', 'button', 'input',
    'select', 'textarea', 'svg', 'picture', 'source', 'wbr'
]);

const TAG_START_RE = /<(\/?)([a-zA-Z][a-zA-Z0-9:_-]*)/y;

export function checkHtmlBalance(code: string): HtmlIssue[] {
    const issues: HtmlIssue[] = [];
    const stack: { name: string; start: number; end: number }[] = [];
    const n = code.length;
    let i = 0;

    while (i < n) {
        const lt = code.indexOf('<', i);
        if (lt === -1) break;

        if (code.startsWith('<!--', lt)) {
            const end = code.indexOf('-->', lt + 4);
            if (end === -1) {
                issues.push({ from: lt, to: n, message: 'Comment is never closed (missing -->)' });
                break;
            }
            i = end + 3;
            continue;
        }
        if (code.startsWith('<!', lt)) {
            const end = code.indexOf('>', lt);
            i = end === -1 ? n : end + 1;
            continue;
        }

        TAG_START_RE.lastIndex = lt;
        const m = TAG_START_RE.exec(code);
        if (!m) {
            i = lt + 1;
            continue;
        }

        const closing = m[1] === '/';
        const name = m[2].toLowerCase();
        let j = TAG_START_RE.lastIndex;
        let inQuote: string | null = null;
        let closedProperly = false;
        let selfClose = false;

        while (j < n) {
            const ch = code[j];
            if (inQuote) {
                if (ch === inQuote) inQuote = null;
                j++;
                continue;
            }
            if (ch === '"' || ch === "'") {
                inQuote = ch;
                j++;
                continue;
            }
            if (ch === '>') {
                selfClose = code[j - 1] === '/';
                j++;
                closedProperly = true;
                break;
            }
            j++;
        }

        if (!closedProperly) {
            issues.push({ from: lt, to: n, message: `<${closing ? '/' : ''}${name}> is never closed (missing >)` });
            break;
        }

        const tagEnd = j;

        if (closing) {
            let idx = -1;
            for (let k = stack.length - 1; k >= 0; k--) {
                if (stack[k].name === name) {
                    idx = k;
                    break;
                }
            }
            if (idx === -1) {
                issues.push({ from: lt, to: tagEnd, message: `Closing tag </${name}> has no matching opening tag` });
            } else {
                for (let k = stack.length - 1; k > idx; k--) {
                    if (!OPTIONAL_END_TAGS.has(stack[k].name)) {
                        issues.push({ from: stack[k].start, to: stack[k].end, message: `<${stack[k].name}> is never closed` });
                    }
                }
                stack.length = idx;
            }
        } else if (!selfClose && !VOID_ELEMENTS.has(name)) {
            const autoCloses = AUTO_CLOSE_ON_SIBLING[name];
            while (stack.length && autoCloses && autoCloses.includes(stack[stack.length - 1].name)) {
                stack.pop();
            }
            if (stack.length && stack[stack.length - 1].name === 'p' && !PHRASING_TAGS.has(name)) {
                stack.pop();
            }
            stack.push({ name, start: lt, end: tagEnd });

            if (RAW_TEXT_ELEMENTS.has(name)) {
                const closeRe = new RegExp(`</${name}\\s*>`, 'i');
                const rest = code.slice(tagEnd);
                const cm = closeRe.exec(rest);
                if (!cm) {
                    issues.push({ from: lt, to: n, message: `<${name}> is never closed` });
                    stack.pop();
                    break;
                }
                j = tagEnd + cm.index;
            }
        }

        i = j;
    }

    for (let k = stack.length - 1; k >= 0; k--) {
        if (!OPTIONAL_END_TAGS.has(stack[k].name)) {
            issues.push({ from: stack[k].start, to: stack[k].end, message: `<${stack[k].name}> is never closed` });
        }
    }

    return issues;
}
