import {
    EditorView,
    lineNumbers,
    highlightActiveLineGutter,
    highlightSpecialChars,
    drawSelection,
    dropCursor,
    rectangularSelection,
    crosshairCursor,
    highlightActiveLine,
    keymap
} from '@codemirror/view';
import { EditorState, Compartment, type Extension } from '@codemirror/state';
import {
    foldGutter,
    foldKeymap,
    indentOnInput,
    bracketMatching,
    syntaxHighlighting,
    defaultHighlightStyle
} from '@codemirror/language';
import { history, historyKeymap, defaultKeymap } from '@codemirror/commands';
import { closeBrackets, closeBracketsKeymap, autocompletion, completionKeymap } from '@codemirror/autocomplete';
import { highlightSelectionMatches, searchKeymap } from '@codemirror/search';
import { html } from '@codemirror/lang-html';
import { css } from '@codemirror/lang-css';
import { javascript } from '@codemirror/lang-javascript';
import { liquid } from '@codemirror/lang-liquid';
import { linter, lintKeymap, type Diagnostic } from '@codemirror/lint';
import { lintCode, type CodeLanguage } from './validators';
import { codeEditorTheme } from './theme';

function languageExtension(language: CodeLanguage): Extension {
    if (language === 'html') return liquid({ base: html() });
    if (language === 'css') return css();
    if (language === 'javascript') return javascript();
    return [];
}

// Same feature set as `codemirror`'s bundled `basicSetup`, except the line-number gutter is
// pulled out into a Compartment: the inline field is too short/narrow for a gutter to be
// useful, so it's only switched on while the editor is reparented into the bigger modal.
const gutterExtensions: Extension = [lineNumbers(), highlightActiveLineGutter()];

function editorExtensions(gutter: Compartment): Extension[] {
    return [
        gutter.of([]),
        highlightSpecialChars(),
        history(),
        foldGutter(),
        drawSelection(),
        dropCursor(),
        EditorState.allowMultipleSelections.of(true),
        indentOnInput(),
        syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
        bracketMatching(),
        closeBrackets(),
        autocompletion(),
        rectangularSelection(),
        crosshairCursor(),
        highlightActiveLine(),
        highlightSelectionMatches(),
        keymap.of([
            ...closeBracketsKeymap,
            ...defaultKeymap,
            ...searchKeymap,
            ...historyKeymap,
            ...foldKeymap,
            ...completionKeymap,
            ...lintKeymap
        ])
    ];
}

export interface CodeEditorHandle {
    view: EditorView;
    getValue(): string;
    setValue(value: string): void;
    reparent(container: HTMLElement): void;
    setLineNumbersVisible(visible: boolean): void;
    destroy(): void;
}

export interface MountCodeEditorOptions {
    container: HTMLElement;
    value: string;
    language: CodeLanguage;
    onChange: (value: string) => void;
}

export function mountCodeEditor({ container, value, language, onChange }: MountCodeEditorOptions): CodeEditorHandle {
    const lintSource = (view: EditorView): Diagnostic[] => lintCode(view.state.doc.toString(), language);
    const gutter = new Compartment();

    const state = EditorState.create({
        doc: value,
        extensions: [
            ...editorExtensions(gutter),
            EditorView.lineWrapping,
            languageExtension(language),
            linter(lintSource, { delay: 300 }),
            codeEditorTheme,
            EditorView.updateListener.of((update) => {
                if (update.docChanged) onChange(update.state.doc.toString());
            })
        ]
    });

    const view = new EditorView({ state, parent: container });

    return {
        view,
        getValue() {
            return view.state.doc.toString();
        },
        setValue(next: string) {
            const current = view.state.doc.toString();
            if (current === next) return;
            view.dispatch({ changes: { from: 0, to: current.length, insert: next } });
        },
        reparent(nextContainer: HTMLElement) {
            nextContainer.appendChild(view.dom);
            view.requestMeasure();
            view.focus();
        },
        setLineNumbersVisible(visible: boolean) {
            view.dispatch({ effects: gutter.reconfigure(visible ? gutterExtensions : []) });
        },
        destroy() {
            view.destroy();
        }
    };
}
