// css-tree (like most tolerant parsers) treats EOF as an implicit close for any still-open
// block, so it never reports "unclosed { ... }" — the single most common CSS mistake.
// This does the one thing css-tree won't: track brace depth (skipping over strings and
// comments) and flag unbalanced braces.

export interface CssIssue {
    from: number;
    to: number;
    message: string;
}

export function checkCssBraceBalance(code: string): CssIssue[] {
    const issues: CssIssue[] = [];
    const openStack: number[] = [];
    const n = code.length;
    let i = 0;

    while (i < n) {
        const ch = code[i];

        if (ch === '/' && code[i + 1] === '*') {
            const end = code.indexOf('*/', i + 2);
            if (end === -1) {
                issues.push({ from: i, to: n, message: 'Comment is never closed (missing */)' });
                return issues;
            }
            i = end + 2;
            continue;
        }
        if (ch === '"' || ch === "'") {
            const quote = ch;
            let j = i + 1;
            while (j < n && code[j] !== quote) {
                if (code[j] === '\\') j++;
                j++;
            }
            i = j + 1;
            continue;
        }
        if (ch === '{') {
            openStack.push(i);
            i++;
            continue;
        }
        if (ch === '}') {
            if (openStack.length === 0) {
                issues.push({ from: i, to: i + 1, message: "Unexpected } with no matching {" });
            } else {
                openStack.pop();
            }
            i++;
            continue;
        }
        i++;
    }

    for (const pos of openStack) {
        issues.push({ from: pos, to: pos + 1, message: '{ is never closed' });
    }

    return issues;
}
