import type { Diagnostic } from '@codemirror/lint';
import { parse as acornParse } from 'acorn';
import * as csstree from 'css-tree';
import { maskLiquid } from './maskLiquid';
import { checkHtmlBalance } from './htmlBalance';
import { checkCssBraceBalance } from './cssBalance';
import { createLiquidEngine } from './liquidTags';

export type CodeLanguage = 'html' | 'css' | 'javascript' | 'text';

function clampRange(from: number, to: number, docLength: number): [number, number] {
    const start = Math.max(0, Math.min(from, docLength));
    const end = Math.max(start, Math.min(to, docLength));
    return [start, end === start ? Math.min(start + 1, docLength) : end];
}

function lintLiquid(code: string): Diagnostic[] {
    try {
        createLiquidEngine().parse(code);
        return [];
    } catch (e: any) {
        const token = e?.token;
        const from = typeof token?.begin === 'number' ? token.begin : 0;
        const to = typeof token?.end === 'number' ? token.end : from + 1;
        const [start, end] = clampRange(from, to, code.length);
        return [{ from: start, to: end, severity: 'warning', message: `Liquid: ${String(e?.message ?? e).split('\n')[0]}` }];
    }
}

function lintHtml(code: string): Diagnostic[] {
    const masked = maskLiquid(code);
    return checkHtmlBalance(masked).map(({ from, to, message }) => {
        const [start, end] = clampRange(from, to, code.length);
        return { from: start, to: end, severity: 'warning', message } as Diagnostic;
    });
}

function lintCss(code: string): Diagnostic[] {
    const masked = maskLiquid(code);
    const diagnostics: Diagnostic[] = [];

    diagnostics.push(
        ...checkCssBraceBalance(masked).map(({ from, to, message }) => {
            const [start, end] = clampRange(from, to, code.length);
            return { from: start, to: end, severity: 'warning', message: `CSS: ${message}` } as Diagnostic;
        })
    );

    try {
        csstree.parse(masked, {
            positions: true,
            onParseError(error: any) {
                const offset = typeof error.offset === 'number' ? error.offset : 0;
                const [start, end] = clampRange(offset, offset + 1, code.length);
                diagnostics.push({ from: start, to: end, severity: 'warning', message: `CSS: ${error.message}` });
            }
        });
    } catch (error: any) {
        const offset = typeof error?.offset === 'number' ? error.offset : 0;
        const [start, end] = clampRange(offset, offset + 1, code.length);
        diagnostics.push({ from: start, to: end, severity: 'warning', message: `CSS: ${error?.message ?? error}` });
    }
    return diagnostics;
}

function lintJavascript(code: string): Diagnostic[] {
    const masked = maskLiquid(code);
    try {
        acornParse(masked, { ecmaVersion: 'latest', sourceType: 'script', allowReturnOutsideFunction: true });
        return [];
    } catch (e: any) {
        const pos = typeof e?.pos === 'number' ? e.pos : 0;
        const [start, end] = clampRange(pos, pos + 1, code.length);
        const message = String(e?.message ?? e).replace(/\s*\(\d+:\d+\)\s*$/, '');
        return [{ from: start, to: end, severity: 'warning', message: `JS: ${message}` }];
    }
}

export function lintCode(code: string, language: CodeLanguage): Diagnostic[] {
    if (!code) return [];

    const diagnostics = lintLiquid(code);

    if (language === 'html') diagnostics.push(...lintHtml(code));
    else if (language === 'css') diagnostics.push(...lintCss(code));
    else if (language === 'javascript') diagnostics.push(...lintJavascript(code));

    return diagnostics.sort((a, b) => a.from - b.from);
}
